typedef int* PtrToInt;
typedef int const* CPtrToInt;

int x = 10;
int y = 20;

// Surprising: int* const p (Constant pointer)
const PtrToInt p = &x;

// Expected: const int* q (Pointer to constant data)
CPtrToInt q = &y;

// OK: Data is mutable through p
*p = 42;

// Error: p cannot be reassigned
// p = &y;

// Error: q points to immutable data
// *q = 50;

// OK: q can be reassigned
q = &x;
